"""Lowest Common Ancestor of a Binary Tree — bottom-up recursion.

A node is the answer when p and q are found in different subtrees, or when the
node itself is one of them and the other lies below.

Time: O(n)   Space: O(h)
"""
if "TreeNode" not in globals():
    class TreeNode:
        def __init__(self, val=0, left=None, right=None):
            self.val = val
            self.left = left
            self.right = right


class Solution:
    def lowestCommonAncestor(self, root, p, q):
        if root is None or root is p or root is q:
            return root
        left = self.lowestCommonAncestor(root.left, p, q)
        right = self.lowestCommonAncestor(root.right, p, q)
        if left and right:
            return root
        return left or right
